To prevent potential Cross-Site Scripting (XSS) vulnerabilities (e.g., via `javascript:` or `data:` URIs), it is highly recommended to validate that the URL protocol is safe (i.e., starts with `http://` or `https://`) before rendering it in an <a> tag or passing it to `window.open`.

```
export function OriginLink({ href, label }: { href: string; label: string }): ReactElement {
  if (href.length === 0) {
    return <span className="origin-missing">{label}: source pending</span>;
  }

  const lowerHref = href.toLowerCase();
  const isSafe = lowerHref.startsWith("http://") || lowerHref.startsWith("https://");
  if (!isSafe) {
    return <span className="origin-missing">{label}: invalid link</span>;
  }

  return <a href={href} onClick={(event) => openExternalLink(event, href)} rel="noreferrer" target="_blank" title={href}>{label} <FiExternalLink aria-hidden="true" /></a>;
}
