![security-critical](https://www.gstatic.com/codereviewagent/security-critical.svg) ![critical](https://www.gstatic.com/codereviewagent/critical.svg)

Using `execSync` with string interpolation of directory paths (`cwd`, `repoRoot`) introduces a command injection vulnerability. If the current working directory contains shell metacharacters (such as `;`, `` ` ``, or `$()`), they will be executed by the shell. Additionally, directory paths containing single quotes will break the SQL query syntax.

To resolve this, use `execFileSync` to execute `git` and `sqlite3` directly without spawning a shell, and escape single quotes in the directory paths to prevent SQL injection/syntax errors.

```javascript
function _detectSessionModel() {
  try {
    const dbPath = join(
      process.env.XDG_DATA_HOME || join(homedir(), ".local/share"),
      "opencode",
      "opencode.db",
    );
    if (!existsSync(dbPath)) return "";

    // Find the most recent session in this directory
    const cwd = process.cwd();
    let repoRoot = cwd;
    try {
      repoRoot = execFileSync("git", ["rev-parse", "--show-toplevel"], {
        encoding: "utf-8",
        timeout: 2000,
        stdio: ["pipe", "pipe", "pipe"],
      }).trim() || cwd;
    } catch {
      // Fallback to cwd if git command fails
    }

    const dirList = [cwd, repoRoot, repoRoot.split(".")[0]]
      .filter((d) => d && d !== "/" && d !== "/tmp")
      .map((d) => "'" + d.replace(/'/g, "''") + "'")
      .join(", ");

    if (!dirList) return "";

    const sessionId = execFileSync(
      "sqlite3",
      [
        dbPath,
        "SELECT id FROM session WHERE directory IN (" + dirList + ") ORDER BY time_created DESC LIMIT 1",
      ],
      { encoding: "utf-8", timeout: 2000, stdio: ["pipe", "pipe", "pipe"] },
    ).trim();

    if (!sessionId) return "";

    const safeSessionId = sessionId.replace(/'/g, "''");

    const modelId = execFileSync(
      "sqlite3",
      [
        dbPath,
        "SELECT json_extract(data, '$.model.modelID') FROM message WHERE session_id='" + safeSessionId + "' AND json_extract(data, '$.model.modelID') IS NOT NULL LIMIT 1",
      ],
      { encoding: "utf-8", timeout: 2000, stdio: ["pipe", "pipe", "pipe"] },
    ).trim();

    const providerId = execFileSync(
      "sqlite3",
      [
        dbPath,
        "SELECT json_extract(data, '$.model.providerID') FROM message WHERE session_id='" + safeSessionId + "' AND json_extract(data, '$.model.modelID') IS NOT NULL LIMIT 1",
      ],
      { encoding: "utf-8", timeout: 2000, stdio: ["pipe", "pipe", "pipe"] },
    ).trim();

    if (providerId && modelId) return providerId + "/" + modelId;
    if (modelId) return modelId;
    return "";
  } catch {
    return "";
  }
}
```

