![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

If `durationMs` is `undefined`, strict equality checks against `null` will fail, leading to incorrect bucket categorization (e.g., returning `"30m+"` instead of `"duration pending"`) or rendering `"NaNm"` in the UI. Using loose equality `== null` safely covers both `null` and `undefined` values.

```
function durationBucket(durationMs: number | null | undefined): string {
  if (durationMs == null) {
    return "duration pending";
  }
  if (durationMs < 300000) {
    return "under 5m";
  }
  if (durationMs < 1800000) {
    return "5m-30m";
  }

  return "30m+";
}

function durationLabel(durationMs: number | null | undefined): string {
  if (durationMs == null) {
    return "duration pending";
  }

  return `${Math.round(durationMs / 60000)}m`;
}
```

